add('03_004','春子向右侧脸极近景，耳、眼、刘海填幅。',['春子'],[],['内眉高外眉低','目光朝右下'],'灰色简化底面',[],'Reaction，紧盯右下，短吸气后准备倒数；不提前变眼形。',['眼睛凝视右下',['眨眼短合又开','下颌压低一点'],'无回应使质问收紧','目光和眉形仍压向右下'],'短沉默近景与下一源格正面下刀形成不同视角；没有空转侧头。',2,['100mm平视春子侧脸极近景，耳廓在左，眼睛与鼻尖在右，头发纵向充满上下边缘；固定机位。','春子盯着画面右下方，眼皮短短合过一次，随即重新压低；她吸入一口短气，下颌微收，脸部停在向右的侧向，内眉持续高挑。','侧脸后方背景呈深灰蓝低亮层，水面远光柔弱，轮廓不抢眼。','无台词。','冷白侧光轻亮鼻尖、耳缘与眼下，刘海下阴影清晰，内眉斜线保持可读。','一口短吸气，低柔水声持续。'],flags=['P'])
